use std::collections::BTreeSet;
use std::fs::{read_to_string, write};

const SOURCE_GLOB: &str = "../css_ast/src/**/*.rs";
const TABLE_PATH: &str = "../css_value_definition_parser/src/sized_types.rs";

fn render(names: &BTreeSet<String>) -> String {
	let mut out = String::from(
		"// AUTO-GENERATED by csskit_source_finder's `sized_types` test. Run `mise run generate-sized-types` to regenerate.\n\
		 // Do not edit this file directly.\n\
		 \n\
		 pub(crate) const SIZED_TYPES: &[&str] = &[\n",
	);
	for name in names {
		out.push('\t');
		out.push('"');
		out.push_str(name);
		out.push_str("\",\n");
	}
	out.push_str(
		"];\n\
		 \n\
		 /// Returns `true` if `name` is a css_ast type that carries no `'a` lifetime parameter, and so\n\
		 /// must be referenced as `name` (not `name<'a>`) when substituted into a value slot.\n\
		 pub(crate) fn is_sized_type(name: &str) -> bool {\n\
		 \tSIZED_TYPES.binary_search(&name).is_ok()\n\
		 }\n",
	);
	out
}

#[test]
fn sized_types_table_is_current() {
	let names = csskit_source_finder::find_sized_types(SOURCE_GLOB, |_| {});
	let expected = render(&names);

	if std::env::var_os("REGENERATE_SIZED_TYPES").is_some() {
		write(TABLE_PATH, &expected).expect("write sized_types.rs");
		return;
	}

	let current = read_to_string(TABLE_PATH).expect("read sized_types.rs");
	assert_eq!(
		current,
		expected,
		"{TABLE_PATH} is stale ({} types scanned). Run `mise run generate-sized-types` to regenerate.",
		names.len()
	);
}
